 async startUmpire(){const s=this.state.activeMatches[this.currentCourt];if(!s)return U.toast('Load trận trước','err');const court=this.state.courts[this.currentCourt];if(T.Auth.role()==='UMPIRE'&&court?.umpireUid&&court.umpireUid!==T.Auth.user?.uid)U.toast('Sân đang gán trọng tài khác; quyền UMPIRE đầy đủ vẫn cho phép tiếp quản chấm điểm.','info');s.started=true;s.updatedAt=Date.now();const m=this.state.matches[s.matchId],before=U.clone(m),after={...m,status:'LIVE',courtId:this.currentCourt,startedAt:Date.now()};const c=this.state.courts[this.currentCourt];const updates={};updates[T.Data.path('activeMatches/'+this.currentCourt)]=s;if(!this.state.config.rulesLocked){updates[T.Data.path('config/rulesLocked')]=true;updates[T.Data.path('config/lockedAt')]=Date.now();this.state.config={...this.state.config,rulesLocked:true,lockedAt:Date.now()};}updates[T.Data.path('matches/'+m.id)]=after;updates[T.Data.path('courts/'+this.currentCourt)]={...c,status:'LIVE',activeMatchId:m.id};await T.Data.queueMulti(updates,{type:'MATCH_START'});await this.logEvent('MATCH_STARTED',s,null,null);await T.Data.audit('START','match',m.id,before,after);this.comment(`Trận đấu giữa ${this.teamName(m.teamAId)} và ${this.teamName(m.teamBId)} chính thức bắt đầu.`);},
 async score(side,delta){const s=this.state.activeMatches[this.currentCourt];if(!s)return U.toast('Chưa load trận','err');try{const result=T.Scoring.point(s,side,delta,this.state.config.rules),eventId=U.id('evt'),evt={id:eventId,seq:(s.version||0)+1,type:delta>0?'POINT_AWARDED':'POINT_CORRECTED',side,delta,before:result.before,after:result.after,matchId:s.matchId,courtId:this.currentCourt,actorUid:T.Auth.user?.uid||'local',clientAt:Date.now()};this.state.activeMatches[this.currentCourt]=result.state;const updates={};updates[T.Data.path('activeMatches/'+this.currentCourt)]=result.state;updates[T.Data.path('events/'+this.currentCourt+'/'+eventId)]=evt;await T.Data.queueMulti(updates,{eventId,type:'SCORE'});this.renderUmpire();const m=this.state.matches[s.matchId];if(delta>0)this.comment(this.buildScoreCommentary(m,result,side));if(result.setFinished)U.toast('Set đã kết thúc. Xác nhận sang set tiếp theo.','ok');}catch(e){U.toast(e.message,'err')}},
