 async resetSet(){const ok=await U.confirmDanger('Reset set hiện tại','Hành động này đưa tỷ số set về 0-0.','RESET');if(!ok)return;const s=U.clone(this.state.activeMatches[this.currentCourt]);if(!s)return;const before=U.clone(s);s.sets[s.setIndex]={a:0,b:0,finished:false};s.version++;await T.Data.queueSet('activeMatches/'+this.currentCourt,s,{type:'RESET_SET'});await this.logEvent('SET_RESET',s,before,s);await T.Data.audit('RESET_SET','match',s.matchId,before,s);},
 async endMatch(){const s=this.state.activeMatches[this.currentCourt];if(!s)return;const ok=await U.confirmDanger('Kết thúc trận đấu','Sẽ khóa điểm và cập nhật BXH.','KẾT THÚC');if(!ok)return;const m=this.state.matches[s.matchId],w=T.Scoring.winner(s.sets,this.state.config.rules);if(!w)return U.toast('Chưa xác định đội thắng đủ set','err');const after={...m,status:'FINISHED',sets:s.sets,winnerId:w==='A'?m.teamAId:m.teamBId,finishedAt:Date.now()};const c=this.state.courts[this.currentCourt],eventId=U.id('evt');const evt={id:eventId,type:'MATCH_FINISHED',matchId:m.id,courtId:this.currentCourt,winnerId:after.winnerId,clientAt:Date.now(),actorUid:T.Auth.user?.uid||'local'};const updates={};updates[T.Data.path('matches/'+m.id)]=after;updates[T.Data.path('activeMatches/'+this.currentCourt)]=null;updates[T.Data.path('courts/'+this.currentCourt)]={...c,status:'AVAILABLE',activeMatchId:''};updates[T.Data.path('events/'+this.currentCourt+'/'+eventId)]=evt;await T.Data.queueMulti(updates,{eventId,type:'MATCH_FINISHED'});await T.Data.audit('FINISH','match',m.id,m,after);this.comment(`Kết thúc trận đấu. ${this.teamName(after.winnerId)} giành chiến thắng.`);},
