 fullscreenVideo(){const box=document.getElementById('video-box');if(document.fullscreenElement)document.exitFullscreen();else box.requestFullscreen?.().catch(()=>box.classList.toggle('pseudo-full'))},fitVideo(){document.getElementById('video-box').classList.remove('pseudo-full');document.body.style.zoom='1';},
