 renderRegistrationPublic(){if(location.hash==='#register'){document.getElementById('public-register').classList.remove('hidden');document.getElementById('login-screen').classList.add('hidden')}if(location.hash.startsWith('#spectator')){document.documentElement.classList.add('tk-public-spectator-boot');document.getElementById('public-spectator').classList.remove('hidden');document.getElementById('login-screen').classList.add('hidden');this.startSpectator()}},
