 async importBackup(file){if(!file)return;const ok=await U.confirmDanger('Khôi phục dữ liệu','Dữ liệu hiện tại có thể bị ghi đè.','KHÔI PHỤC');if(!ok)return;const data=JSON.parse(await file.text());const updates={};for(const [k,v] of Object.entries(data.state||{}))if(['config','teams','matches','courts','finance','announcements','registrations'].includes(k))updates[T.Data.path(k)]=v;await T.Data.queueMulti(updates,{type:'RESTORE'});await T.Data.audit('RESTORE','tournament',T.Data.tid,null,{exportedAt:data.exportedAt});},
