 updateDeleteScopeUI(){const range=document.querySelector('input[name="delete-scope"]:checked')?.value!=='all';document.getElementById('delete-from').disabled=!range;document.getElementById('delete-to').disabled=!range;this.previewScheduleDelete(false)},
 scheduleDeletePlan(){const scope=document.querySelector('input[name="delete-scope"]:checked')?.value||'range',from=document.getElementById('delete-from').value,to=document.getElementById('delete-to').value,category=document.getElementById('delete-category').value||'ALL',stage=document.getElementById('delete-stage').value||'ALL',allowProtected=document.getElementById('delete-protected').checked;if(scope==='range'&&(!from||!to||to<from))throw new Error('Vui lòng chọn khoảng ngày hợp lệ');const all=Object.values(this.state.matches||{}),inScope=m=>(category==='ALL'||this.normalizeCategory(m.category)===category)&&(stage==='ALL'||String(m.stage||'').toUpperCase()===stage)&&(scope==='all'||(m.date&&m.date>=from&&m.date<=to)),activeIds=new Set(Object.values(this.state.activeMatches||{}).filter(Boolean).map(x=>x.matchId)),isProtected=m=>activeIds.has(m.id)||['LIVE','FINISHED','WALKOVER','RETIRED','DISQUALIFIED','SUSPENDED'].includes(m.status)||(m.sets||[]).length>0||!!m.startedAt||!!m.finishedAt,candidates=all.filter(inScope),protectedMatches=candidates.filter(isProtected),deletable=candidates.filter(m=>allowProtected||!isProtected(m)),skipped=allowProtected?[]:protectedMatches;return{scope,from,to,category,stage,allowProtected,candidates,protectedMatches,deletable,skipped,activeIds}},
