 async unlockSecurity(){if(T.Auth?.role?.()!=='ADMIN')return;const password=$('tk9-unlock-password').value;try{const snap=await T.Data.db.ref(this.secretPath()).once('value'),s=snap.val();if(!s?.salt||!s?.hash)return U.toast('Chưa thiết lập mật khẩu firewall','err');const hash=await this.pbkdf2(password,s.salt,s.iterations||120000);if(hash!==s.hash)return U.toast('Mật khẩu firewall không đúng','err');this.securityLocked=false;sessionStorage.setItem(`tk9_security_unlocked_${SPORT_KEY}_${T.Data.tid}`,'1');document.body.classList.remove('tk9-copy-locked');$('tk9-unlock-password').value='';$('tk9-unlock-pop').classList.add('hidden');this.renderSecurityCorner();U.toast('Đã mở khóa chống sao chép cho phiên này','ok')}catch(e){U.toast(e.message,'err')}},
 renderSecurityCorner(){const sec=App.state.config?.security||{},corner=$('tk9-firewall-corner');if(!corner)return;corner.classList.toggle('hidden',!sec.enabled&&!sec.copyProtection);const unlocked=sessionStorage.getItem(`tk9_security_unlocked_${SPORT_KEY}_${T.Data.tid}`)==='1';if(unlocked)this.securityLocked=false;const locked=this.securityLocked||!unlocked;$('tk9-firewall-state').textContent=locked?'🔒 Chống sao chép đang khóa':'🔓 ADMIN đã mở';$('tk9-firewall-open').classList.toggle('hidden',T.Auth?.role?.()!=='ADMIN'||!locked);document.body.classList.toggle('tk9-copy-locked',!!sec.copyProtection&&locked);},
