const $=id=>document.getElementById(id);
const TERMINAL=new Set(['FINISHED','CANCELLED','WALKOVER','RETIRED','DISQUALIFIED']);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
