function refreshProtectedValues(){
 const out=new Set(),add=v=>{if(typeof v==='string'){const x=v.trim();if(x)out.add(x);}};
 try{
  const st=window.Topkey?.App?.state||{};
  const cfg=st.config||{},ap=cfg.appearance||{};[cfg.title,cfg.location,ap.titlePrimary,ap.titleSecondary,ap.eventTime].forEach(add);
  Object.values(st.teams||{}).forEach(x=>[x?.code,x?.name,x?.p1,x?.p2,x?.dept].forEach(add));
  Object.values(st.courts||{}).forEach(x=>[x?.name].forEach(add));
  Object.values(st.announcements||{}).forEach(x=>[x?.title,x?.body,x?.author].forEach(add));
  Object.values(st.finance||{}).forEach(x=>[x?.note,x?.description,x?.ref,x?.receiptNo].forEach(add));
  Object.values(st.registrations||{}).forEach(x=>[x?.name,x?.p1,x?.p2,x?.dept,x?.contact].forEach(add));
  Object.values(st.users||{}).forEach(x=>[x?.displayName,x?.email].forEach(add));
 }catch{}
 protectedSet=out;return out;
}
function isProtectedExact(s){return protectedSet.has(String(s||'').trim());}
