function patchPreview(){const base=App.renderSchedulePreview?.bind(App);if(!base||App.__u39PreviewRender)return;App.__u39PreviewRender=true;App.renderSchedulePreview=function(result,...args){const out=base(result,...args),box=$('schedule-preview-box');if(!box||!result?.requiredReport?.length)return out;const wrap=document.createElement('div');wrap.className='tk39-required-summary';const b=document.createElement('b');b.textContent=tr('\ud83d\udd12 Rule b\u1eaft bu\u1ed9c theo V\u0110V','\ud83d\udd12 Required player/day rules','\ud83d\udd12 \u8fd0\u52a8\u5458/\u65e5\u671f\u5fc5\u987b\u89c4\u5219');wrap.appendChild(b);const chips=document.createElement('div');chips.className='tk39-required-chips';result.requiredReport.forEach(r=>{const s=document.createElement('span');s.className='tk39-required-result '+(r.ok?'ok':'bad');s.textContent=`${r.name} \u00b7 ${fmtDate(r.date)} \u00b7 ${r.count}/${r.max}`;chips.appendChild(s);});wrap.appendChild(chips);box.prepend(wrap);return out;};}
