  const ctx=createContext(result),manual=[],errors=[];const rows=diagnostics.filter(r=>selections[r.match.id]).sort((a,b)=>a.suggestions.length-b.suggestions.length||String(a.match.code||a.match.id).localeCompare(String(b.match.code||b.match.id)));
