  const localCheck=$('tk46-local-only')?.closest('label');if(localCheck)localCheck.title='Chỉ áp dụng cho giọng hệ thống. TOPKEY Offline Voice luôn chạy local trên thiết bị.';
  const h=$('page-live')?.querySelector('h2');
