let offCloud=null,cloudRow=null,lastAppliedRaw='',migrating=false,saving=false,listenerUid='',cloudMode='PRIMARY';
function readLocal(){try{return String(localStorage.getItem(DICT_KEY)||'')}catch{return''}}
