  // Replace only complete score pairs so names, set numbers and other figures are untouched.
  const pair=new RegExp(`(^|[^0-9])${A}\\s*([,\\-–—:])\\s*${B}(?=$|[^0-9])`,'g');
  return text.replace(pair,(all,prefix,sep)=>`${prefix}${b}${sep===','?', ':' - '}${a}`);
