    state.lastName=seg.display||seg.text;let ok=false;const sys=readSettings().preferSystem?chooseZhSystemVoice():null;
    if(sys){state.lastMode='SYSTEM zh-CN';ok=await speakSystem(seg.text,'zh-CN',sys,item,first)}
