function ensureResetModal(){let modal=$('tk87-reset-modal');if(modal)return modal;modal=document.createElement('div');modal.id='tk87-reset-modal';modal.className='modal hidden';modal.innerHTML=`<div class="modal-box tk87-reset-box"><div class="split"><div><h2>↻ Reset tỷ số</h2><p class="muted">Chọn đúng phạm vi cần reset. Hai lựa chọn không xóa đội/VĐV/lịch trận.</p></div><button type="button" class="btn mini" data-tk87-reset-close>✕ Đóng</button></div><div class="tk87-reset-options"><label class="tk87-reset-choice"><input type="radio" name="tk87-reset-mode" value="SET" checked><span><b>Reset hiệp đang tính điểm</b><small>Đưa hiệp hiện tại về 0-0; giữ các hiệp đã hoàn tất và trận vẫn đang LIVE. Cơ chế người phát đầu hiệp giữ đúng contract hiện tại.</small></span></label><label class="tk87-reset-choice tk87-reset-danger"><input type="radio" name="tk87-reset-mode" value="MATCH"><span><b>Reset cả trận · về Chưa thi đấu</b><small>Xóa toàn bộ tỷ số/kết quả, phiên chấm điểm đang treo và trả sân về AVAILABLE. Chỉ ADMIN; lịch, đội và VĐV vẫn giữ.</small></span></label></div><div id="tk87-reset-note" class="tk87-reset-note"></div><div class="action-bar tk87-reset-actions"><button type="button" class="btn" data-tk87-reset-cancel>Hủy</button><button type="button" class="btn danger" id="tk87-reset-confirm">Tiếp tục reset</button></div></div>`;document.body.appendChild(modal);modal.querySelectorAll('[data-tk87-reset-close],[data-tk87-reset-cancel]').forEach(b=>b.onclick=()=>modal.classList.add('hidden'));modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.add('hidden')});$('tk87-reset-confirm').onclick=executeResetChoice;modal.querySelectorAll('input[name="tk87-reset-mode"]').forEach(r=>r.onchange=renderResetModalState);return modal}
